const replacements = new Map([
  ["&", "and"],
  ["é", "e"],
  ["à", "a"]
]);

export default function slugify(value, options = {}) {
  let result = value;
  for (const [from, to] of replacements) {
    result = result.replaceAll(from, to);
  }
  result = result.trim().replaceAll(/\s+/g, "-");
  if (options.strict) result = result.replaceAll(/[^A-Za-z0-9-]/g, "");
  return options.lower ? result.toLowerCase() : result;
}
